<?php
declare(strict_types=1); require_once __DIR__.'/../app/bootstrap.php'; require_admin();$q=trim((string)($_GET['q']??''));$sql='SELECT c.*,COUNT(o.id) orders_count FROM customers c LEFT JOIN orders o ON o.customer_id=c.id';$args=[];if($q!==''){$sql.=' WHERE c.name LIKE ? OR c.nif LIKE ? OR c.phone LIKE ? OR c.email LIKE ?';$args=['%'.$q.'%','%'.$q.'%','%'.$q.'%','%'.$q.'%'];}$sql.=' GROUP BY c.id ORDER BY c.id DESC LIMIT 300';$s=db()->prepare($sql);$s->execute($args);$rows=$s->fetchAll();layout_start('Clientes');echo '<section class="panel"><div class="toolbar"><h2>Clientes registados</h2><form><input name="q" value="'.e($q).'" placeholder="Nome, NIF, telefone ou email" style="min-width:250px"><button>Pesquisar</button></form></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Tipo</th><th>NIF</th><th>Telefone</th><th>Email</th><th>Pedidos</th><th>Estado</th></tr></thead><tbody>';if(!$rows)echo '<tr><td colspan="7" class="empty">Nenhum cliente encontrado.</td></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['customer_type']).'</td><td>'.e($r['nif']?:'—').'</td><td>'.e($r['phone']).'</td><td>'.e($r['email']?:'—').'</td><td>'.(int)$r['orders_count'].'</td><td><span class="badge">'.((int)$r['active']?'Ativo':'Inativo').'</span></td></tr>';echo '</tbody></table></div></section>';layout_end();
